script:
carrier_event = {
	id = action.2100

	hide_window = yes

	is_triggered_only = yes

	trigger = {
		OR = {
			exists = leader
			AND = {
				exists = sector
				exists = sector.sector_capital.leader
			}
		}
	}

	immediate = {
		# Planetary governor takes priority.
		if = {
			limit = {
				exists = leader
			}
			leader = {
				add_experience = 10
			}
		}
		# Otherwise fall back to the sector governor.
		else_if = {
			limit = {
				exists = sector
				exists = sector.sector_capital.leader
			}
			sector.sector_capital.leader = {
				add_experience = 10
			}
		}
	}
}

